constexpr int BLOCK = 256;

// Reverse each block-sized tile of in into out. Launch with BLOCK threads per
// block. Tail threads load a neutral value and still reach the barrier.
__global__ void reverse_tiles(const int *in, int *out, int n) {
  __shared__ int tile[BLOCK];
  const int base = blockIdx.x * BLOCK;
  const int t = threadIdx.x;
  const int valid = min(BLOCK, n - base); // elements owned by this block
  tile[t] = t < valid ? in[base + t] : 0;
  __syncthreads(); // every load is visible before any thread reads the tile
  if (t < valid)
    out[base + t] = tile[valid - 1 - t];
}
// Launch: reverse_tiles<<<(n + BLOCK - 1) / BLOCK, BLOCK>>>(in, out, n);

// One thread computes one C[row, col]. A is M-by-K, B is K-by-N and C is
// M-by-N, all row-major.
__global__ void matmul_naive(const float *A, const float *B, float *C, int M,
                             int N, int K) {
  const int row = blockIdx.y * blockDim.y + threadIdx.y;
  const int col = blockIdx.x * blockDim.x + threadIdx.x;
  if (row >= M || col >= N)
    return; // safe here: no barrier follows
  float sum = 0.0f;
  for (int inner = 0; inner < K; ++inner)
    sum += A[row * K + inner] * B[inner * N + col];
  C[row * N + col] = sum;
}
// Launch: dim3 block(16, 16);
//         dim3 grid((N + 15) / 16, (M + 15) / 16);

constexpr int TILE = 16;

__global__ void tiled_matmul(const float *A, const float *B, float *C, int M,
                             int N, int K) {
  __shared__ float As[TILE][TILE];
  __shared__ float Bs[TILE][TILE];
  const int row = blockIdx.y * TILE + threadIdx.y;
  const int col = blockIdx.x * TILE + threadIdx.x;
  float sum = 0.0f;
  for (int phase = 0; phase < (K + TILE - 1) / TILE; ++phase) {
    const int a_col = phase * TILE + threadIdx.x;
    const int b_row = phase * TILE + threadIdx.y;
    As[threadIdx.y][threadIdx.x] =
        (row < M && a_col < K) ? A[row * K + a_col] : 0.0f;
    Bs[threadIdx.y][threadIdx.x] =
        (b_row < K && col < N) ? B[b_row * N + col] : 0.0f;
    __syncthreads(); // both tiles are complete before any thread reads them
    for (int k = 0; k < TILE; ++k)
      sum += As[threadIdx.y][k] * Bs[k][threadIdx.x];
    __syncthreads(); // all reads finish before the next phase overwrites tiles
  }
  if (row < M && col < N)
    C[row * N + col] = sum; // predicate the store; never return early
}
// Launch: dim3 block(TILE, TILE);
//         dim3 grid((N + TILE - 1) / TILE, (M + TILE - 1) / TILE);

// Sum up to 32 values with exactly one full warp: warp_sum<<<1, 32>>>.
// Every lane executes every shuffle; lanes without data contribute 0.
__global__ void warp_sum(const int *values, int count, int *result) {
  const int lane = threadIdx.x;
  int v = lane < count ? values[lane] : 0;
  const unsigned full = 0xffffffffu; // all 32 lanes participate
  for (int offset = 16; offset > 0; offset /= 2)
    v += __shfl_down_sync(full, v, offset);
  if (lane == 0)
    *result = v; // lane 0 holds the warp total
}

